    // 4. ProcessEth1DataInBlock
    // 5. ProcessOperationsNoVerifyAttsSigs
    // 6. if >= Altair: ProcessSyncAggregate
}
```

FILE 3: beacon-chain/core/blocks/payload.go (ProcessPayload)
```go
func ProcessPayload(st state.BeaconState, body interfaces.ReadOnlyBeaconBlockBody) error {
    payload, err := body.Execution()
    if err := verifyBlobCommitmentCount(st.Slot(), body); err != nil { return err }
    if err := ValidatePayloadWhenMergeCompletes(st, payload); err != nil { return err }
    if err := ValidatePayload(st, payload); err != nil { return err }
    if err := st.SetLatestExecutionPayloadHeader(payload); err != nil { return err }
    return nil
}
```

FILE 4: beacon-chain/core/blocks/withdrawals.go (ProcessWithdrawals lines 154-227)
```go
