```

FILE 5: beacon-chain/core/electra/transition_no_verify_sig.go (ProcessOperations)
```go
func ProcessOperations(ctx context.Context, st state.BeaconState, block interfaces.ReadOnlyBeaconBlock) (state.BeaconState, error) {
    // ProcessProposerSlashings
    // ProcessAttesterSlashings
    // ProcessAttestationsNoVerifySignature
    // ProcessDeposits
    // ProcessVoluntaryExits
    // ProcessBLSToExecutionChanges
    // ProcessDepositRequests (from execution_requests)
    // ProcessWithdrawalRequests (from execution_requests)
    // ProcessConsolidationRequests (from execution_requests)
